use vstd::prelude::*;

verus! {

fn numpy_matrix_transpose(x: Vec<Vec<f32>>) -> (result: Vec<Vec<f32>>)
    requires
        // non‐empty matrix
        x.len() > 0,
        x[0].len() > 0,
        // all rows have the same length
        forall(|i: usize| i < x.len() ==> x[i].len() == x[0].len()),
    ensures
        // the result has as many rows as the input has columns
        result.len() == x[0].len(),
        // each row of the result has length equal to the number of input rows
        forall(|r: usize| r < result.len() ==> result[r].len() == x.len()),
        // transposition property: result[r][c] == x[c][r]
        forall(|r: usize, c: usize| r < result.len() && c < x.len() ==>
            result[r][c] == x[c][r]
        ),
{
    let m = x.len();
    let n = x[0].len();

    // build the output matrix row by row
    let mut result: Vec<Vec<f32>> = Vec::new();
    result.reserve(n);

    let mut j: usize = 0;
    while j < n
        invariant
            j <= n,
            // we have already built j rows
            result.len() == j,
            // for each built row k < j, row k has length m and row[k][u] == x[u][k]
            forall(|k: usize, u: usize| k < j && u < m ==> result[k][u] == x[u][k]),
        decreases n - j,
    {
        // build the j-th row of the transpose by taking column j of x
        let mut row: Vec<f32> = Vec::new();
        row.reserve(m);

        let mut i: usize = 0;
        while i < m
            invariant
                i <= m,
                // we have pushed i elements so far
                row.len() == i,
                // for each u < i, row[u] == x[u][j]
                forall(|u: usize| u < i ==> row[u] == x[u][j]),
            decreases m - i,
        {
            row.push(x[i][j]);
            i += 1;
        }

        result.push(row);
        j += 1;
    }

    result
}

} // verus!

